// Step 2: Prepare data for AI Router
const item = $input.item;
const lineEvent = item.json.body?.events?.[0];
const userData = item.json.userDataFromSheet;

// Determine action from postback or text
let action = 'unknown';
if (lineEvent.postback?.data) {
  try {
    action = JSON.parse(lineEvent.postback.data).action;
  } catch {
    action = lineEvent.postback.data;
  }
}

const userMessage = lineEvent.message?.text || '';
const isExistingUser = item.json.isExistingUser;

// Construct a clear prompt for the AI
const routingPrompt = `
You are a helpful assistant for a vaccine booking system.
Based on the user's latest message and action, determine the primary intent.

Previous conversation summary is not available.
User's message: "${userMessage}"
Rich menu action: "${action}"
Is the user already registered?: ${isExistingUser}

Your task is to respond with a JSON object that routes the user to the correct function. The possible routes are: 'register', 'booking', 'status_check', 'contact_info', or 'unknown'.

- If the user wants to book a vaccine, route to 'booking'.
- If the user wants to check their appointment status, route to 'status_check'.
- If the user is new and needs to register, or asks how to register, route to 'register'.
- If the user asks for contact information or help, route to 'contact_info'.
- Otherwise, route to 'unknown'.

Respond with ONLY the JSON object.
`;

// Prepare the request for the OpenAI node
item.json.openai_request = {
  model: 'gpt-4o',
  messages: [{ role: 'user', content: routingPrompt }],
  response_format: { type: 'json_object' }, // Force JSON output
  temperature: 0
};

return item;

// This node prepares the reply message for the user
const item = $input.item;
const route = JSON.parse(item.json.choices[0].message.content).route;

let responseText = '';

if (route === 'status_check') {
  // Logic for checking status would go here in a real scenario
  // For now, we'll use a placeholder message.
  // In a full implementation, you'd fetch data from the 'Appointments' sheet.
  responseText = 'คุณเลือกเมนูตรวจสอบสถานะ ขณะนี้ฟังก์ชันนี้กำลังอยู่ในระหว่างการพัฒนาค่ะ';
} else if (route === 'booking') {
  responseText = 'คุณเลือกเมนูจองวัคซีน กรุณาระบุประเภทวัคซีนที่ต้องการค่ะ';
} else if (route === 'register') {
  responseText = 'คุณเลือกเมนูลงทะเบียนใหม่ กรุณาพิมพ์ชื่อและนามสกุลเพื่อเริ่มค่ะ';
} else if (route === 'contact_info') {
  responseText = 'คุณสามารถติดต่อเจ้าหน้าที่ได้ที่เบอร์ 02-123-4567 ค่ะ';
} else {
  responseText = 'ขออภัยค่ะ ฉันไม่เข้าใจคำสั่งของคุณ กรุณาเลือกจากเมนูหลักค่ะ';
}

// Format the message for LINE API
item.json.responseMessages = [
  {
    type: 'text',
    text: responseText,
  }
];

return item;
